import {esc} from '../../ui/format.js';
import {TYPES,RELATIONS,FIELDS,PROCESS,POOLS,fields,effective} from '../../core/model.js';
import {STEREOTYPES} from '../../core/mbse.js';
import {specificationFields,parameterProvenance} from '../library/inspector.js';
const selectOptions=(items,value)=>items.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('');
export function renderInspector({m,selected,selectedEdge}){const n=id=>m.nodes.find(x=>x.id===id);if(selectedEdge){const e=m.edges.find(e=>e.id===selectedEdge);if(e)return `<h3>Relație</h3><p class="small">${esc(n(e.from)?.name)} → ${esc(n(e.to)?.name)}</p><span class="badge">${esc(RELATIONS[e.type])}</span><form id="edge-form">${e.type==='flow'?`<label>Pondere rutare<input name="weight" type="number" min=".0001" step="any" value="${e.weight}" required></label><label>Transport (s)<input name="delay" type="number" min="0" max="86400" step="any" value="${e.delay}" required></label><p class="small muted">Ponderile ieșirilor sunt normalizate la fiecare alegere; piesa urmează o singură rută.</p>`:['requires','consumes','produces','staffedBy'].includes(e.type)?`<label>Cantitate per piesă<input name="quantity" type="number" min="1" step="1" value="${e.quantity}" required></label>`:'<p class="small muted">Relație descriptivă; fără efect numeric implicit.</p>'}${edgeMetadata(e)}<button type="submit" class="primary">Salvează relația</button></form><button data-action="delete-edge" class="danger">Șterge relația</button>`}
 const el=n(selected);if(!el)return `<h3>Proprietăți</h3><p class="muted small">Selectează un element sau o relație. Creează surse, operații și ieșiri pentru a defini procesul.</p><div class="notice">Personalul, HW și SW influențează calculul prin relații «Necesită resursă». Materialele prin «Consumă material».</div>`;const p=effective(m,el);return `<div class="panelhead"><h3>${esc(TYPES[el.type])}</h3><span class="badge">${PROCESS.includes(el.type)||POOLS.includes(el.type)||['source','sink','material'].includes(el.type)?'Parametrizabil':'Descriptiv'}</span></div><form id="node-form"><label>Nume<input name="name" value="${esc(el.name)}" required maxlength="160"></label><label>Descriere<textarea name="description">${esc(el.description)}</textarea></label><label>Părinte în structură<select name="parent"><option value="">— Rădăcină —</option>${selectOptions(m.nodes.filter(x=>x.id!==el.id).map(x=>[x.id,x.name]),el.parent)}</select></label>${fields(el.type).map(k=>`<label>${esc(FIELDS[k][0])} <small>${FIELDS[k][1]}</small><input name="p-${k}" type="number" min="${FIELDS[k][2]}" max="${FIELDS[k][3]}" step="${['capacity','buffer','limit'].includes(k)?1:'any'}" value="${p[k]}" ${el.bindings[k]?'readonly':''} required><select name="b-${k}" aria-label="Variabilă pentru ${esc(FIELDS[k][0])}"><option value="">Valoare locală</option>${selectOptions(m.variables.filter(v=>v.unit===FIELDS[k][1]).map(v=>[v.id,v.name+' = '+v.value]),el.bindings[k])}</select>${parameterProvenance(el,k)}</label>`).join('')}${specificationFields(el)}${nodeMetadata(el)}<button type="submit" class="primary">Salvează elementul</button></form>${portsInspector(el)}<h3 class="spaced">Atribute personalizate</h3>${el.attributes.map((a,i)=>`<div class="attribute"><b>${esc(a.name)}</b><span>${esc(a.value)} ${esc(a.unit)}</span><button data-edit-attribute="${i}">Editează</button><button data-attribute="${i}" aria-label="Șterge atribut">×</button></div>`).join('')}<button data-action="attribute">+ Atribut descriptiv</button><p class="small muted">Atributele libere documentează modelul. Numai parametrii de mai sus și variabilele legate de ei influențează calculul.</p><button data-action="hide-node">Ascunde din diagramă</button><button data-action="delete-node" class="danger">Șterge din model</button><p class="small muted">ID: ${esc(el.id)}</p>`}
function edgeMetadata(e){return `<label>Etichetă / mesaj<input name="label" value="${esc(e.label||'')}"></label>${e.type==='message'?`<label>Ordine mesaj<input name="order" type="number" min="1" max="100" value="${e.order||1}"></label>`:''}${['transition','controlFlow','objectFlow','message'].includes(e.type)?['guard','trigger','effect'].map(k=>`<label>${k}<input name="${k}" value="${esc(e[k]||'')}"></label>`).join(''):''}${['association','composition','aggregation'].includes(e.type)?['sourceMultiplicity','targetMultiplicity'].map(k=>`<label>${k}<input name="${k}" placeholder="0..*" value="${esc(e[k]||'')}"></label>`).join(''):''}`}
function nodeMetadata(el){return `<details class="property-section"><summary>Definiție MBSE</summary><label>Stereotipuri (separate prin virgulă)<input name="stereotypes" value="${esc((el.stereotypes||[]).join(', '))}" list="stereotypes"></label><datalist id="stereotypes">${STEREOTYPES.map(s=>`<option value="${s}">`).join('')}</datalist><label>Nivel MOFLT<select name="moflt">${selectOptions([['','—'],['M','Mission'],['O','Operational'],['F','Functional'],['L','Logical'],['T','Technical']],el.moflt)}</select></label><label>Proprietăți · nume:tip=valoare<textarea name="properties" placeholder="mass:kg=12">${esc((el.properties||[]).map(p=>p.name+':'+p.type+'='+p.value).join('\n'))}</textarea></label><label>Comportament / constrângere / criteriu test<textarea name="behavior">${esc(el.behavior||'')}</textarea></label><p class="small muted">Definițiile MBSE și expresiile sunt descriptive. Parametrii numerici ai procesului alimentează simularea.</p></details>`}
function portsInspector(el){return `<h3>Porturi & interfețe</h3>${(el.ports||[]).map(p=>`<div class="attribute"><b>${esc(p.name)}</b><span>${esc(p.kind+' · '+p.direction+' · '+p.payload)}</span><button data-portdelete="${esc(p.id)}" title="Șterge port">×</button></div>`).join('')}<button data-action="add-port">+ Port tipizat</button><p class="small muted">Click pe pătratul unui port sursă, apoi pe portul destinație. Tipul relației se alege în paletă; direcțiile și tipurile sunt verificate.</p>${['machine','robot','hardware','tool'].includes(el.type)?'<button data-action="assign-operator">+ Alocă operator la utilaj</button>':''}<button data-action="save-template">▤ Salvează în biblioteca mea</button>`}
